import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const headerLine = JSON.stringify({
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 10,
  r_val: 20,
  expected_frechet: 1.2,
  bbox: [0, 0, 100, 100],
  stream: [[0, 0], [10, 10], [20, 5]],
}) + "\n";
let pendingTrace = null;

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 12, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    pendingTrace = res;
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end("not found"); return; }
    const type = filePath.endsWith(".js") ? "text/javascript" : "text/html";
    res.writeHead(200, { "Content-Type": type });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

function freeze(page) {
  return page.addStyleTag({
    content: ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }",
  });
}

async function loadUntilReady(page) {
  await page.goto(origin, { waitUntil: "load" });
  await page.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await freeze(page);
  pendingTrace = null;
  await page.selectOption("#traceSelect", "1");
  await page.click("#loadBtn");
  await page.waitForSelector("#traceLoadingHud.visible");
  pendingTrace.writeHead(200, { "Content-Type": "application/x-ndjson" });
  pendingTrace.write(headerLine);
  await page.waitForFunction(() => document.body.classList.contains("playback-ready"));
  await page.waitForTimeout(250);
}

function measure() {
  const box = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return null;
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    return {
      id: sel,
      display: cs.display,
      visibility: cs.visibility,
      top: Math.round(r.top),
      bottom: Math.round(r.bottom),
      left: Math.round(r.left),
      right: Math.round(r.right),
      width: Math.round(r.width),
      height: Math.round(r.height),
      paddingBottom: cs.paddingBottom,
    };
  };
  const overlap = (a, b) => {
    if (!a || !b) return null;
    const x = Math.max(0, Math.min(a.right, b.right) - Math.max(a.left, b.left));
    const y = Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top));
    return { x, y, area: x * y };
  };
  const header = box("header");
  const params = box("#paramsBar");
  const canvasWrap = box("#canvasWrap");
  const canvas = box("#canvasContainer");
  const sidebar = box("#sidebar");
  const dock = box("#mobileTransport");
  const playback = box("#playbackBar");
  const title = document.querySelector("header h1");
  const titleBox = box("header h1");
  const lastSection = box("#sidebar .section:last-child");
  const layers = box("#layersSection");
  const panelOpen = box("#mobilePanelOpen");
  const instructions = box("#sidebar .section:last-child");
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  return {
    inner: { vw, vh, scrollWidth: document.documentElement.scrollWidth, scrollHeight: document.documentElement.scrollHeight },
    classes: document.body.className,
    header, params, canvasWrap, canvas, sidebar, dock, playback, titleBox, lastSection, layers, panelOpen, instructions,
    titleOverflow: title ? { scrollWidth: title.scrollWidth, clientWidth: title.clientWidth } : null,
    dockOverSidebar: overlap(dock, sidebar),
    dockOverLastSection: overlap(dock, lastSection),
    dockOverCanvas: overlap(dock, canvas),
    gapCanvasToSidebar: sidebar && canvas ? sidebar.top - canvas.bottom : null,
    paramsText: document.getElementById("paramsBar")?.innerText.replace(/\s+/g, " ").trim(),
    uploadStatus: document.getElementById("uploadStatus")?.innerText,
    uploadStatusDisplay: getComputedStyle(document.getElementById("uploadStatus")).display,
    fileControlsDisplay: getComputedStyle(document.querySelector(".file-controls")).display,
  };
}

try {
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await loadUntilReady(mobile);
  const readyTop = await mobile.evaluate(measure);
  await mobile.screenshot({ path: "/tmp/pwshot/mobile-ready-viewport.png" });

  await mobile.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await mobile.waitForTimeout(150);
  const readyBottom = await mobile.evaluate(measure);
  await mobile.screenshot({ path: "/tmp/pwshot/mobile-ready-scrolled.png" });

  // Close status panel if possible
  const closeVisible = await mobile.evaluate(() => {
    const btn = document.getElementById("mobilePanelClose");
    return btn && getComputedStyle(btn).display !== "none";
  });
  if (closeVisible) {
    await mobile.click("#mobilePanelClose");
    await mobile.waitForTimeout(150);
  }
  const panelClosed = await mobile.evaluate(measure);
  await mobile.screenshot({ path: "/tmp/pwshot/mobile-ready-panel-closed.png" });

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await loadUntilReady(desktop);
  const desktopReady = await desktop.evaluate(measure);
  await desktop.screenshot({ path: "/tmp/pwshot/desktop-ready.png" });

  const mid = await browser.newPage({ viewport: { width: 900, height: 700 }, deviceScaleFactor: 1 });
  await loadUntilReady(mid);
  const midReady = await mid.evaluate(measure);
  await mid.screenshot({ path: "/tmp/pwshot/desktop-900-ready.png" });

  console.log(JSON.stringify({ readyTop, readyBottom, panelClosed, desktopReady, midReady }, null, 2));
} finally {
  await browser.close();
  server.close();
}

