import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [] }));
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end("not found"); return; }
    res.writeHead(200, { "Content-Type": filePath.endsWith(".js") ? "text/javascript" : "text/html" });
    res.end(data);
  });
});
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

try {
  const fixture = await browser.newPage({ viewport: { width: 430, height: 1400 }, deviceScaleFactor: 1 });
  await fixture.goto(pathToFileURL(path.join(usability, "mobile-dock-sidebar.html")).href, { waitUntil: "domcontentloaded" });
  await fixture.screenshot({ path: path.join(usability, "mobile-dock-sidebar.png"), fullPage: true });

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await mobile.goto(origin, { waitUntil: "domcontentloaded" });
  await mobile.evaluate(() => {
    document.body.classList.add("trace-loaded-mobile", "playback-ready");
    document.getElementById("dropHint").style.display = "none";
    document.getElementById("sidebar").style.display = "flex";
    const dock = document.getElementById("mobileTransport");
    dock.classList.add("visible");
    document.getElementById("paramsBar").innerHTML = `
      <span class="params-metric params-metric--blue params-metric--frechet"><span class="params-metric-body"><span class="params-metric-label">Computed Fréchet distance</span><b class="params-metric-value">0.1842</b></span></span>
      <span class="params-metric params-metric--blue params-metric--time"><span class="params-metric-body"><span class="params-metric-label">Simplification time</span><b class="params-metric-value">42.1800 ms</b></span></span>`;
    document.getElementById("statusIndices").innerHTML = `
      <div class="status-idx-block">
        <span class="idx-label" style="color:#ff9f43">p (start)</span>
        <span class="idx-num" style="color:#ff9f43">#0</span>
      </div>
      <div class="status-idx-block">
        <span class="idx-label" style="color:#ff7ae8">v_i (current)</span>
        <span class="idx-num" style="color:#ff7ae8">#1</span>
      </div>`;
    document.getElementById("statusGrid").innerHTML = `
      <span>step</span><span class="mono"><b>1</b></span>
      <span>alive</span><span class="mono"><b>1</b> / 1</span>`;
  });
  await mobile.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await mobile.waitForTimeout(80);
  const scrolled = await mobile.evaluate(() => {
    const last = document.querySelector("#sidebar .section:last-child").getBoundingClientRect();
    const dock = document.getElementById("mobileTransport").getBoundingClientRect();
    return {
      scrollY: Math.round(window.scrollY),
      scrollHeight: document.documentElement.scrollHeight,
      lastBottom: Math.round(last.bottom),
      dockTop: Math.round(dock.top),
      overlap: Math.max(0, Math.min(last.bottom, dock.bottom) - Math.max(last.top, dock.top)),
    };
  });
  await mobile.screenshot({ path: path.join(usability, "mobile-dock-sidebar-scrolled-live.png") });

  const loading = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await loading.goto(origin, { waitUntil: "domcontentloaded" });
  const loadingState = await loading.evaluate(() => {
    document.body.classList.add("trace-loaded-mobile", "trace-loading");
    document.getElementById("dropHint").style.display = "none";
    document.getElementById("traceLoadingHud").classList.add("visible");
    return {
      scrollHeight: document.documentElement.scrollHeight,
      vh: window.innerHeight,
      sidebarDisplay: getComputedStyle(document.getElementById("sidebar")).display,
      hud: getComputedStyle(document.getElementById("traceLoadingHud")).display,
    };
  });

  const start = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await start.goto(origin, { waitUntil: "domcontentloaded" });
  const startState = await start.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    innerWidth: window.innerWidth,
  }));

  console.log(JSON.stringify({ scrolled, loadingState, startState }, null, 2));
} finally {
  await browser.close();
  server.close();
}
